/usr/bin/bash -lc "python - <<'PY'
from zipfile import ZipFile
from lxml import etree
p='repo/features/steps/test_files/blk-paras-and-tables.docx'
with ZipFile(p) as z: root=etree.fromstring(z.read('word/document.xml'))
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
body=root.find('w:body',ns)
for x in body:
 tag=etree.QName(x).localname
 if tag=='p':
  print('P', ''.join(x.xpath('.//w:t/text()',namespaces=ns)))
 elif tag=='tbl': print('TABLE', ''.join(x.xpath('.//w:t/text()',namespaces=ns)))
 else: print(tag)
PY
sed -n '1,120p' repo/TARGET_CONTRACTS.md"

